import {test} from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
import {GameAudio,SOUNDS,type Cue} from '../src/presentation/audio';import {ChaosSounds} from '../src/presentation/chaos-sounds';import {isSoundClick} from '../src/presentation/ui-sounds';import {Moments} from '../src/presentation/moments';import {Simulation} from '../src/simulation/world';import {capture,type FrogState} from '../src/simulation/state';import {OutbreakRules} from '../src/game/outbreak';import {FreezeRules,FREEZE} from '../src/game/freeze-tag';import {ClassicRules,CLASSIC} from '../src/game/classic-tag';import type {ArenaChaosState} from '../src/chaos/arena-chaos';
const playing=()=>{const r=new OutbreakRules([0,1,2],0,{announcementTicks:0,countdownTicks:0,graceTicks:60});r.advanceClock(0);return r.view(0);};
const frogs=()=>capture(new Simulation()).frogs;
const arena=(stage:'gust'|'calm'|'warning'='calm'):ArenaChaosState=>({start:0,ballCycle:0,nextBall:0,deferredSpawn:false,platforms:[],balls:[],wind:{stage,direction:1,remaining:60}});
function recorder(){const calls:{cue:Cue;intensity:number}[]=[],stops:(Cue|undefined)[]=[];const sounds=new ChaosSounds({play:(cue,intensity=1)=>calls.push({cue,intensity}),silence:cue=>stops.push(cue)});return{sounds,calls,stops};}
test('all modes emit exactly 3, 2, 1 and distinct GO once through real round clocks',()=>{for(const mode of['poison','freeze','classic']){const r=mode==='freeze'?new FreezeRules([0,1,2],0):mode==='classic'?new ClassicRules([0,1,2],0):new OutbreakRules([0,1,2],0),m=new Moments(),events:{cue:Cue;number:number}[]=[];for(let tick=0;tick<=245;tick++){r.advanceClock(tick);const view=r.view(tick);for(const e of m.update(view,0))if(e.cue==='count'||e.cue==='go')events.push({cue:e.cue,number:Math.ceil(view.remainingMs/1000)});assert.deepEqual(m.update(view,0),[]);}assert.deepEqual(events.filter(e=>e.cue==='count').map(e=>e.number),[3,2,1]);assert.equal(events.filter(e=>e.cue==='go').length,1);assert.notDeepEqual(SOUNDS.count.notes,SOUNDS.go.notes);}});
test('poison/classic tags get poof, remote/local freezes get ice and rescues get a thaw sound',()=>{for(const mode of['poison','freeze','classic']){const t={announcementTicks:0,countdownTicks:0,graceTicks:60},r=mode==='freeze'?new FreezeRules([0,1,2],0,{...FREEZE,...t}):mode==='classic'?new ClassicRules([0,1,2],0,{...CLASSIC,...t}):new OutbreakRules([0,1,2],0,t);r.advanceClock(0);const m=new Moments();m.update(r.view(0),2);r.infect(1,[[0,1]]);const events=m.update(r.view(1),2);assert.ok(events.some(e=>(e.sound??e.cue)===(mode==='freeze'?'freeze':'infect')));assert.deepEqual(m.update(r.view(1),2),[]);if(mode==='freeze'){r.infect(2,[[2,1]]);assert.ok(m.update(r.view(2),2).some(e=>(e.sound??e.cue)==='rescue'));}}});
test('last tag ending a round still sounds, while results and rule timing remain unchanged',()=>{const r=new FreezeRules([0,1],0,{...FREEZE,announcementTicks:0,countdownTicks:0}),m=new Moments();r.advanceClock(0);m.update(r.view(0),0);r.infect(1,[[0,1]]);assert.equal(r.phase,'round-results');const events=m.update(r.view(1),0);assert.ok(events.some(e=>e.cue==='round'));assert.ok(events.some(e=>e.sound==='freeze'));});
test('boings, teleport, bubble pop, sticky contact and gravity edges sound once and coalesce eight frogs',()=>{const r=recorder(),view=playing(),s=frogs();r.sounds.update(s,undefined,view,0,[],0);const mappings=[['pogoTick','boing'],['balloonPopTick','boing'],['bumperTick','boing'],['swapTick','teleport'],['bubbleEscapeTick','bubble_pop'],['stickyAttachTick','sticky'],['gravityFlipTick','go']]as const;let n=1;for(const[field,cue]of mappings){s.forEach(f=>(f as any)[field]=n++);r.calls.length=0;r.sounds.update(s,undefined,view,0,[],1000+n);assert.equal(r.calls.filter(e=>e.cue===cue).length,1,field);assert.equal(r.calls.find(e=>e.cue===cue)?.intensity,cue==='sticky'?.8:1);r.calls.length=0;r.sounds.update(s,undefined,view,0,[],1001+n);assert.equal(r.calls.length,0);}s[0].swapTick=100;const old=s[0].swapTick;r.sounds.update(s,undefined,view,0,[],2000);s[0].swapTick=90;r.sounds.update(s,undefined,view,0,[],2001);r.calls.length=0;s[0].swapTick=old;r.sounds.update(s,undefined,view,0,[],2002);assert.equal(r.calls.length,0,'correction must not replay the same event');});
test('wind plays only during active gusts, is bounded and stops on calm, results or reset',()=>{const r=recorder(),s=frogs(),view=playing();for(let now=0;now<=2000;now+=16)r.sounds.update(s,arena('gust'),view,0,['windy_weather'],now);assert.equal(r.calls.filter(e=>e.cue==='wind').length,4);r.calls.length=0;r.sounds.update(s,arena('calm'),view,0,['windy_weather'],2100);assert.equal(r.calls.length,0);assert.ok(r.stops.includes('wind'));r.sounds.update(s,arena('gust'),{...view,phase:'round-results'},0,['windy_weather'],2200);assert.equal(r.calls.length,0);});
test('Magnet Mouths chirps near a real assisted target, never for baseline assistance or historical state',()=>{const r=recorder(),s=frogs(),view=playing();r.sounds.update(s,undefined,view,0,['magnet_mouths'],0);s[0].aimAssistTick=1;s[0].aimAssistTarget=1;s[0].tongue={phase:'flying',direction:{x:1,y:0},tip:{x:s[1].x-1,y:s[1].y},distance:2,length:2};r.sounds.update(s,undefined,view,0,[],100);assert.equal(r.calls.length,0);r.sounds.update(s,undefined,view,0,['magnet_mouths'],101);assert.equal(r.calls.filter(e=>e.cue==='magnet').length,1);r.sounds.update(s,undefined,view,0,['magnet_mouths'],102);assert.equal(r.calls.filter(e=>e.cue==='magnet').length,1);const fresh=recorder();fresh.sounds.update(s,undefined,view,0,['magnet_mouths'],103);assert.equal(fresh.calls.length,0);});
test('menu, fullscreen, diagnostics, summaries and icon-button descendants click; disabled/mute/action-pad do not duplicate',()=>{const target=(id:string,disabled=false)=>({closest:()=>({id,matches:()=>disabled})})as any;for(const id of['ready','help','fullscreen','mobile-export','input-monitor-toggle','menu-resume',''])assert.ok(isSoundClick(target(id)));for(const id of['sound','touch-action'])assert.equal(isSoundClick(target(id)),false);assert.equal(isSoundClick(target('start',true)),false);assert.equal(isSoundClick(null),false);});
test('wind/noise voices share eight-source budget, do not mask actions, and mute/hidden/zero-volume stay silent',()=>{const doc=Object.getOwnPropertyDescriptor(globalThis,'document'),perf=Object.getOwnPropertyDescriptor(globalThis,'performance');let now=1000;Object.defineProperty(globalThis,'document',{configurable:true,value:{hidden:false}});Object.defineProperty(globalThis,'performance',{configurable:true,value:{now:()=>now}});const param=()=>({value:0,setValueAtTime(){},linearRampToValueAtTime(){},exponentialRampToValueAtTime(){},setTargetAtTime(){}}),node=()=>({connect(){},disconnect(){},start(){},stop(){(this as any).onended?.();},onended:undefined as any});let buffers=0;const ctx:any={state:'running',currentTime:0,sampleRate:48000,createOscillator:()=>({...node(),frequency:param()}),createGain:()=>({...node(),gain:param()}),createBiquadFilter:()=>({...node(),frequency:param()}),createBufferSource:()=>node(),createBuffer:(_n:number,length:number)=>{buffers++;return{getChannelData:()=>new Float32Array(length)};}};const a=new GameAudio();a.context=ctx;a.master=ctx.createGain();a.enabled=true;try{a.play('wind');a.play('jump');assert.equal(a.played,2,'ambient noise must not eat local action cooldown');a.silence('wind');assert.equal(a.voices.size,1,'only wind stops');for(const cue of['freeze','boing','bubble_pop','teleport','sticky','infect']as Cue[]){now+=600;a.play(cue);}assert.ok(a.peakVoices<=8);assert.equal(buffers,1);a.toggle();assert.equal(a.voices.size,0);const played=a.played;now+=1000;a.play('go');assert.equal(a.played,played);a.enabled=true;(document as any).hidden=true;a.play('go');assert.equal(a.played,played);(document as any).hidden=false;a.setVolume(0);a.play('go');assert.equal(a.played,played);}finally{if(doc)Object.defineProperty(globalThis,'document',doc);else delete(globalThis as any).document;if(perf)Object.defineProperty(globalThis,'performance',perf);}});
test('new coverage preserves all approved gameplay, CPU, viewport and input source bytes',()=>{const m=JSON.parse(readFileSync('docs/sound-coverage-preservation.json','utf8')),h=(s:any)=>createHash('sha256').update(s).digest('hex');for(const[p,hash]of Object.entries(m.protected))assert.equal(h(readFileSync(p)),hash,p);for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(h(r.original),r.beforeSha256,p);assert.equal(h(readFileSync(p)),r.afterSha256,p);}});
